# Databricks notebook source
"""Spark Declarative Pipeline generated by Data Model Studio.

Model: tawal_tower_infrastructure (medallion) → target hec_demo_catalog.tawal_generated
Source tables ingest raw files from SOURCE_VOLUME with Auto Loader; downstream
tables read their upstream and project the modeled columns. Search for TODO to
add business logic (joins, derivations) the model alone can't express.
"""
from pyspark import pipelines as dp
from pyspark.sql import functions as F

CATALOG = spark.conf.get("target_catalog", "hec_demo_catalog")
SCHEMA = spark.conf.get("target_schema", "tawal_generated")
SOURCE_VOLUME = spark.conf.get("source_volume_path", "/Volumes/hec_demo_catalog/tawal_raw/landing")

@dp.table(
    name="bronze_regions",
    comment="Raw regions file",
)
@dp.expect_or_drop("valid_region_id", "region_id IS NOT NULL")
def bronze_regions():
    path = f"{SOURCE_VOLUME}/regions"
    df = (
        spark.readStream.format("cloudFiles")
        .option("cloudFiles.format", "csv")
        .option("header", "true")
        .option("cloudFiles.inferColumnTypes", "true")
        .load(path)
    )
    df = df.withColumn("_ingested_at", F.current_timestamp())
    df = df.withColumn("_source_file", F.col("_metadata.file_path"))
    df = df.withColumn("_batch_id", F.date_format(F.current_timestamp(), "yyyyMMddHHmmss"))
    return df

